    "procedure": "1. Прогрейте АКПП до 50-60 °C (по диагностике или после поездки), установите автомобиль строго горизонтально.\n2. Слейте ATF через сливную пробку в мерную тару, зафиксируйте объём.\n3. Установите новую шайбу/уплотнение сливной пробки, затяните пробку (обычно 35 Н·м — сверять по мануалу).\n4. Через заливную трубку/щуп залейте объём, равный слитому.\n5. Запустите двигатель, пройдите селектором все диапазоны. При температуре 50-60 °C проверьте уровень по щупу или контрольной пробке, при необходимости доливайте.\n6. Перелив так же вреден, как недолив. После тест-драйва повторно проверьте уровень и отсутствие течей.",
