      "oem_filter_internal_info": "При обычной сервисной замене масла поддон не снимается (слив через сливную пробку) либо фильтр встроен и не сервисируется. Для замены фильтра потребовалось бы снятие КПП / разборка; OEM фильтра для стандартного ТО не указывается.",
