    "procedure": "1. Прогрейте АКПП до рабочей температуры (≈40–50 °C), установите автомобиль строго горизонтально.\n2. Слейте ATF через сливную пробку в мерную тару, зафиксируйте объём.\n3. Снимите нижний поддон, замените фильтр и прокладку. Очистите магниты и поддон.\n4. Установите поддон с новыми болтами/прокладкой, момент затяжки по мануалу применения.\n5. Залейте свежую ATF в объёме, близком к слитому.\n6. Запустите двигатель, пройдите селектором все диапазоны. При температуре 35-45 °C выставьте уровень по контрольной пробке или щупу.\n7. После тест-драйва проверьте герметичность и уровень.",
